import type { HttpLogOutcome, InfiniteLogBaseRecord, InfiniteLogDataSource, InfiniteLogField, InfiniteLogFilters, InfiniteLogMetadata, InfiniteLogPage, InfiniteLogPageRequest, InfiniteLogRecord, InfiniteLogSort, LogFacetValue, LogMethod, LogRangeFacet, LogValueFacet, NumericRange, } from "./infinite-log-types";
import { getInfiniteLogFieldValue, isHttpInfiniteLogRecord, resolveInfiniteLogFields, } from "./infinite-log-fields";
const textCollator = new Intl.Collator(undefined, {
    numeric: true,
    sensitivity: "base",
});
const outcomes: readonly HttpLogOutcome[] = ["success", "warning", "error"];
const timingKeys = ["dns", "connection", "tls", "ttfb", "transfer"] as const;
const timelineBucketCount = 60;
const timelineDurations = [
    60000,
    5 * 60000,
    15 * 60000,
    60 * 60000,
    6 * 60 * 60000,
    12 * 60 * 60000,
    24 * 60 * 60000,
    7 * 24 * 60 * 60000,
] as const;
type SortValue = number | string;
interface CursorPayload {
    version: 1;
    snapshotRevision: string;
    field: InfiniteLogSort["field"];
    direction: InfiniteLogSort["direction"];
    value: SortValue;
    id: string;
}
function throwIfAborted(signal: AbortSignal) {
    if (signal.aborted) {
        throw new DOMException("The request was aborted.", "AbortError");
    }
}
function toLower(value: string | undefined) {
    return value?.toLocaleLowerCase() ?? "";
}
function matchesText(value: string, query: string) {
    return toLower(value).includes(toLower(query.trim()));
}
function includesAny<T>(values: readonly T[], value: T) {
    return values.length === 0 || values.includes(value);
}
function matchesRange(value: number, range?: NumericRange) {
    if (!range)
        return true;
    if (range.min !== undefined && value < range.min)
        return false;
    if (range.max !== undefined && value > range.max)
        return false;
    return true;
}
function toTimestamp(value: string) {
    const timestamp = Date.parse(value);
    return Number.isNaN(timestamp) ? undefined : timestamp;
}
export function matchesInfiniteLogRecord<TRecord extends InfiniteLogBaseRecord>(record: TRecord, filters: InfiniteLogFilters, fields?: readonly InfiniteLogField<TRecord>[]) {
    const query = filters.query.trim();
    const searchableValues = fields
        ? fields
            .filter((field) => field.type !== "json")
            .map((field) => getInfiniteLogFieldValue(record, field))
        : Object.values(record).filter((value) => typeof value === "string" || typeof value === "number" || typeof value === "boolean");
    if (query &&
        !searchableValues.some((candidate) => matchesText(String(candidate ?? ""), query))) {
        return false;
    }
    if (isHttpInfiniteLogRecord(record)) {
        const httpRecord = record as unknown as InfiniteLogRecord;
        if (!matchesText(httpRecord.host, filters.host))
            return false;
        if (!matchesText(httpRecord.pathname, filters.pathname))
            return false;
        if (!includesAny(filters.outcomes, httpRecord.outcome))
            return false;
        if (!includesAny(filters.statuses, httpRecord.status))
            return false;
        if (!includesAny(filters.methods, httpRecord.method))
            return false;
        if (!includesAny(filters.regions, httpRecord.region))
            return false;
        if (!matchesRange(httpRecord.latency, filters.latency))
            return false;
        for (const key of timingKeys) {
            if (!matchesRange(httpRecord.timing[key], filters.timing?.[key]))
                return false;
        }
    }
    if (filters.timeRange) {
        const timestamp = toTimestamp(record.timestamp);
        const from = toTimestamp(filters.timeRange.from);
        const to = toTimestamp(filters.timeRange.to);
        if (timestamp === undefined ||
            from === undefined ||
            to === undefined ||
            timestamp < from ||
            timestamp >= to) {
            return false;
        }
    }
    const fieldById = new Map(fields?.map((field) => [field.id, field]));
    for (const [fieldId, filter] of Object.entries(filters.fields ?? {})) {
        const value = getInfiniteLogFieldValue(record, fieldById.get(fieldId) ?? fieldId);
        if (filter.operator === "contains" && !matchesText(String(value ?? ""), filter.value))
            return false;
        if (filter.operator === "isAnyOf" && !filter.value.some((candidate) => String(candidate) === String(value)))
            return false;
        if (filter.operator === "isBetween") {
            if (typeof value !== "number" || !matchesRange(value, filter.value))
