function getCursorStartIndex<TRecord extends InfiniteLogBaseRecord>(records: readonly TRecord[], cursor: string | undefined, snapshotRevision: string, sort: InfiniteLogSort, fields?: readonly InfiniteLogField<TRecord>[]) {
    if (!cursor)
        return 0;
    const payload = decodeCursor(cursor);
    if (payload.snapshotRevision !== snapshotRevision ||
        payload.field !== sort.field ||
        payload.direction !== sort.direction) {
        throw new Error("The log page cursor does not belong to this query.");
    }
    const cursorIndex = records.findIndex((record) => record.id === payload.id &&
        getInfiniteLogSortValue(record, sort.field, fields) === payload.value);
    if (cursorIndex < 0) {
        throw new Error("The log page cursor no longer points to this snapshot.");
    }
    return cursorIndex + 1;
}
function withoutOwnFacetFilter(filters: InfiniteLogFilters, key: "outcomes" | "statuses" | "methods" | "regions" | "host" | "pathname" | "latency") {
    if (key === "host" || key === "pathname")
        return { ...filters, [key]: "" };
    return { ...filters, [key]: key === "latency" ? undefined : [] };
}
function withoutOwnTimingFilter(filters: InfiniteLogFilters, key: keyof InfiniteLogRecord["timing"]) {
    const { [key]: _removed, ...remainingTiming } = filters.timing ?? {};
    return {
        ...filters,
        timing: Object.keys(remainingTiming).length > 0 ? remainingTiming : undefined,
    };
}
function createValueFacet<T extends string | number>(records: readonly InfiniteLogRecord[], valueForRecord: (record: InfiniteLogRecord) => T, compare: (left: T, right: T) => number): LogValueFacet<T> {
    const counts = new Map<T, number>();
    for (const record of records) {
        const value = valueForRecord(record);
        counts.set(value, (counts.get(value) ?? 0) + 1);
    }
    const values: LogFacetValue<T>[] = [...counts.entries()]
        .map(([value, count]) => ({ value, count }))
        .sort((left, right) => compare(left.value, right.value));
