function createRangeFacet(records: readonly InfiniteLogRecord[], valueForRecord: (record: InfiniteLogRecord) => number): LogRangeFacet {
    if (records.length === 0)
        return {};
    const values = records.map(valueForRecord);
    return { min: Math.min(...values), max: Math.max(...values) };
