        rows,
        metadata,
        loading,
        refreshing,
        fetchingMore,
        error: error?.error,
        errorPhase: error?.phase,
        hasNextPage: Boolean(nextCursor),
        liveAvailable: liveSupported,
        liveEligible,
        liveBoundary,
        pendingLiveCount: pendingLiveRows.length,
        loadMore,
        refresh,
        retry,
        applyPendingLiveRows,
        setAtTop,
    };
