import type { InfiniteLogBaseRecord, InfiniteLogField, InfiniteLogFieldFilterType, InfiniteLogFieldType, } from "./infinite-log-types";
const sampleLimit = 100;
const facetLimit = 24;
export function humanizeInfiniteLogField(id: string) {
    return id
        .replace(/\[(\d+)\]/g, " $1 ")
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .replace(/[._-]+/g, " ")
        .trim()
        .replace(/\b\w/g, (character) => character.toUpperCase());
}
export function getInfiniteLogFieldValue<TRecord extends InfiniteLogBaseRecord>(record: TRecord, field: Pick<InfiniteLogField<TRecord>, "id" | "accessor"> | string) {
    if (typeof field !== "string" && field.accessor)
        return field.accessor(record);
    const id = typeof field === "string" ? field : field.id;
    return id.split(".").reduce<unknown>((value, segment) => {
        if (!value || typeof value !== "object")
            return undefined;
        return (value as Record<string, unknown>)[segment];
    }, record);
}
function inferType(id: string, values: readonly unknown[]): InfiniteLogFieldType {
    if (id === "timestamp" || values.some((value) => value instanceof Date))
        return "datetime";
    const value = values.find((candidate) => candidate !== null && candidate !== undefined);
    if (typeof value === "number")
        return "number";
    if (typeof value === "boolean")
        return "boolean";
    if (typeof value === "object")
        return "json";
    return "text";
}
function inferFilter(type: InfiniteLogFieldType, values: readonly unknown[]): InfiniteLogFieldFilterType {
    if (type === "number")
        return "numberRange";
    if (type === "boolean")
        return "multiSelect";
    if (type === "datetime" || type === "json")
        return "none";
    const comparableValues = values.filter((value): value is string | number | boolean => typeof value === "string" || typeof value === "number" || typeof value === "boolean");
    const uniqueCount = new Set(comparableValues.map(String)).size;
