          <span>Max.</span>
          <output className="min-w-0 truncate tabular-nums text-fg-default">{range[1]} ms</output>
        </span>
      </div>
      <div data-slot="timing-phase-range-control" onKeyUp={commitKeyboardRange} onPointerUp={() => commitRange(rangeRef.current)}>
        <Slider disabled={facet?.max === undefined} formatValue={(current) => `${current} ms`} label={label} max={domain.max} min={domain.min} onChange={updateRange} showHoverPreview={false} showValue={false} step={domain.step} value={range} valuePosition="top"/>
      </div>
    </Field>);
}
